#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "gpio_toggle"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN_2 2
#define GPIO_PIN_3 3

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_2 = NULL;
    struct gpiod_line *line_3 = NULL;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    line_2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_PIN_3);
    if (!line_2 || !line_3) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Configure lines as outputs
    ret = gpiod_line_request_output(line_2, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        ret = EXIT_FAILURE;
        goto exit;
    }
    ret = gpiod_line_request_output(line_3, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Toggle GPIOs every 2 seconds
    while (running) {
        ret = gpiod_line_set_value(line_2, 1);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        ret = gpiod_line_set_value(line_3, 0);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        printf("GPIO 2: High, GPIO 3: Low\n");

        sleep(2);

        ret = gpiod_line_set_value(line_2, 0);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        ret = gpiod_line_set_value(line_3, 1);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        printf("GPIO 2: Low, GPIO 3: High\n");

        sleep(2);
    }

    ret = EXIT_SUCCESS;

exit:
    // Release lines
    if (line_2)
        gpiod_line_release(line_2);
    if (line_3)
        gpiod_line_release(line_3);

    // Close chip
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

