        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines as outputs
    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO 2 as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line3, CONSUMER, 0);
