    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 2

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto exit;
    }

    // Request the line as an output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        ret = EXIT_FAILURE;
        goto exit;
    }

    while (running) {
        // Toggle the GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            ret = EXIT_FAILURE;
            break;
        }

        value = !value;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            ret = EXIT_FAILURE;
            break;
        }

        // Report the state
        printf("GPIO %d set to %d\n", GPIO_LINE, value);

        // Wait for 5 seconds
        sleep(5);
    }

exit:
    // Release the GPIO line
    if (line)
        gpiod_line_release(line);

    // Close the GPIO chip
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

