#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

#define ADS1115_OS_SINGLE 0x8000
#define ADS1115_MUX_P0_N1 0x0000
#define ADS1115_PGA_6_144V 0x0200
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_MODE_SINGLE 0x0000
#define ADS1115_COMP_MODE_TRAD 0x0000
#define ADS1115_COMP_POL_ACT_LOW 0x0000
#define ADS1115_COMP_LAT_NONLAT 0x0000
#define ADS1115_COMP_QUE_DISABLE 0x0000

#define ADS1115_CONFIG_DEFAULT (ADS1115_OS_SINGLE | ADS1115_MUX_P0_N1 | ADS1115_PGA_6_144V | ADS1115_DR_128SPS | ADS1115_MODE_SINGLE | ADS1115_COMP_MODE_TRAD | ADS1115_COMP_POL_ACT_LOW | ADS1115_COMP_LAT_NONLAT | ADS1115_COMP_QUE_DISABLE)

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    uint8_t config[3];
    uint8_t data[2];
    int16_t adc_value;

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Set the slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure the ADS1115
    config[0] = ADS1115_REG_CONFIG >> 8;
    config[1] = ADS1115_REG_CONFIG & 0xFF;
    config[2] = ADS1115_CONFIG_DEFAULT >> 8;
    config[3] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (write(i2c_fd, config, 3) != 3) {
        perror("Failed to write to the i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read the conversion register
        if (write(i2c_fd, &ADS1115_REG_CONVERSION, 1) != 1) {
            perror("Failed to write to the i2c device");
            break;
        }
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from the i2c device");
            break;
        }

        // Combine bytes to form the 16-bit value
        adc_value = (data[0] << 8) | data[1];

        // Print the ADC value
        printf("ADC Value: %d\n", adc_value);

        // Wait for 0.5 seconds
        usleep(500000);
    }

    // Close the I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

