#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define INTERVAL_US 500000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIO pin as PWM output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Start PWM with frequency 1000 Hz and duty cycle 50%
    if (gpioSetPWMfrequency(GPIO_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_PIN, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutycycle(GPIO_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output started on GPIO %d\n", GPIO_PIN);

    // Main loop
    while (running) {
        // Sleep for 0.5 seconds
        gpioDelay(INTERVAL_US);
    }

    // Clean up
    gpioSetPWMdutycycle(GPIO_PIN, 0);
    gpioTerminate();
    printf("PWM output stopped and resources released\n");

    return EXIT_SUCCESS;
}

