        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0 && running) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) / 1e3 > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo\n");
                break;
            }
        }

        if (!running) break;

        if (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            while (gpiod_line_get_value(echo_line) == 1 && running) {
                clock_gettime(CLOCK_MONOTONIC, &end);
            }
        }

        if (!running) break;

        if ((end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) / 1e3 > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo to stop\n");
            continue;
        }

        long duration = (end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) / 1e3;
        double distance = duration * 0.034 / 2; // Speed of sound in cm/us divided by 2

        printf("Distance: %.2f cm\n", distance);

        sleep(60);
    }

    // Release resources
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

