#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_P0_N1 0x0000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_CONFIG_CMODE_TRAD 0x0000

#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_P0_N1 | \
                               ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE | \
                               ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CMODE_TRAD | \
                               ADS1115_CONFIG_CLAT_NONLAT | ADS1115_CONFIG_CPOL_ACTVLOW)

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint16_t config = ADS1115_CONFIG_DEFAULT;
    uint8_t buffer[3];

    // Set up signal handler for graceful exit
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure the ADS1115
    buffer[0] = ADS1115_REG_CONFIG >> 8;
    buffer[1] = ADS1115_REG_CONFIG & 0xFF;
    buffer[2] = config >> 8;
    buffer[3] = config & 0xFF;

    if (write(i2c_fd, buffer, 3) != 3) {
        perror("Failed to write configuration to ADS1115");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Start a conversion
        buffer[0] = ADS1115_REG_CONFIG >> 8;
        buffer[1] = ADS1115_REG_CONFIG & 0xFF;
        buffer[2] = config >> 8;
        buffer[3] = config & 0xFF;

        if (write(i2c_fd, buffer, 3) != 3) {
            perror("Failed to start conversion");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for the conversion to complete
        usleep(13000); // 128 SPS -> ~7.8 ms per conversion

        // Read the conversion result
        buffer[0] = ADS1115_REG_CONVERSION;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write register address for conversion read");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read conversion result");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        uint16_t adc_value = (buffer[0] << 8) | buffer[1];

        // Check if the reading is valid
        if (adc_value == 0xFFFF || adc_value == 0x0000) {
            fprintf(stderr, "Invalid ADC reading\n");
            continue;
        }

        // Print the reading
        printf("ADC Reading: %d\n", adc_value);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

