#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI7021_ADDRESS 0x40
#define MEASURE_TEMP_NO_HOLD 0xF3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint8_t command = MEASURE_TEMP_NO_HOLD;
    uint8_t data[3];

    // Set up signal handler for graceful exit
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDRESS) < 0) {
        perror("Failed to set the I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Send the command to measure temperature
        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to send command to SI7021");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for the measurement to complete (typically 85 ms)
        usleep(85000);

        // Read the temperature measurement
        if (read(i2c_fd, data, 3) != 3) {
            perror("Failed to read temperature from SI7021");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Check the validity of the reading
        if ((data[2] & 0xFC) != 0x00) {
            fprintf(stderr, "Invalid temperature reading\n");
            continue;
        }

        // Calculate the temperature in Celsius
        uint16_t temp_raw = (data[0] << 8) | data[1];
        double temperature = (temp_raw * 175.72 / 65536.0) - 46.85;

        // Print the temperature
        printf("Temperature: %.2f C\n", temperature);

        // Sleep for 5 seconds before the next reading
        sleep(5);
    }

    // Close the I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

