    cleanup();
    exit(EXIT_FAILURE);
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    uint16_t config = ADS1115_REG_CONFIG_OS_SINGLE | ADS1115_REG_CONFIG_MUX_DIFF_0_1 |
                      ADS1115_REG_CONFIG_PGA_6_144V | ADS1115_REG_CONFIG_MODE_CONTINUOUS |
                      ADS1115_REG_CONFIG_DR_128SPS | ADS1115_REG_CONFIG_CMODE_TRAD |
                      ADS1115_REG_CONFIG_CPOL_ACTVLOW | ADS1115_REG_CONFIG_CLAT_NONLAT |
                      ADS1115_REG_CONFIG_CQUE_NONE;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure the ADS1115
    uint8_t config_bytes[3];
    config_bytes[0] = ADS1115_REG_POINTER_CONFIG;
    config_bytes[1] = (config >> 8) & 0xFF;
    config_bytes[2] = config & 0xFF;

    if (write(i2c_fd, config_bytes, 3) != 3) {
        perror("Failed to write to the ADS1115");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Read 3 conversions
    for (int i = 0; i < 3; i++) {
        uint8_t read_buffer[2];
        uint16_t adc_value;

        // Start a single conversion
        config_bytes[0] = ADS1115_REG_POINTER_CONFIG;
        config_bytes[1] = (config >> 8) & 0xFF;
        config_bytes[2] = config & 0xFF;

        if (write(i2c_fd, config_bytes, 3) != 3) {
            perror("Failed to start conversion");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Wait for the conversion to complete
        usleep(125000); // 125ms for 128SPS

        // Read the conversion result
        if (read(i2c_fd, read_buffer, 2) != 2) {
            perror("Failed to read from the ADS1115");
            cleanup();
            exit(EXIT_FAILURE);
        }

        adc_value = ((read_buffer[0] << 8) | read_buffer[1]) >> 4; // 12-bit result

        printf("ADC Value: %d\n", adc_value);

        sleep(1); // Wait 1 second between readings
    }

    cleanup();
    return EXIT_SUCCESS;
}

