#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "gpio_control"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PINS {8, 9, 10, 11}

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    int pins[] = GPIO_PINS;
    size_t num_pins = sizeof(pins) / sizeof(pins[0]);
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    ret = gpiod_chip_get_lines(chip, pins, num_pins, &lines);
    if (ret < 0) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines as outputs
    ret = gpiod_line_request_bulk_output(&lines, CONSUMER);
    if (ret < 0) {
        perror("Failed to request GPIO lines as outputs");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Toggle the GPIOs every 0.1 seconds
    while (running) {
        for (size_t i = 0; i < num_pins; i++) {
            ret = gpiod_line_set_value(gpiod_line_bulk_get_line(&lines, i), 1);
            if (ret < 0) {
                perror("Failed to set GPIO line value");
                break;
            }
            printf("GPIO %d set to HIGH\n", pins[i]);
        }

        usleep(100000); // 0.1 seconds

        for (size_t i = 0; i < num_pins; i++) {
            ret = gpiod_line_set_value(gpiod_line_bulk_get_line(&lines, i), 0);
            if (ret < 0) {
                perror("Failed to set GPIO line value");
                break;
            }
            printf("GPIO %d set to LOW\n", pins[i]);
        }

        usleep(100000); // 0.1 seconds
    }

    // Release the lines
    gpiod_line_release_bulk(&lines);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

