void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the lines
    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request trig line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for the echo to start
        struct timespec ts_start, ts_end;
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(echo_line) == 0 && running) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            if (timespec_subtract(&ts_end, &ts_start) > TIMEOUT_US) {
                fprintf(stderr, "Echo did not start\n");
                break;
            }
        }

        if (!running) break;

        // Wait for the echo to stop
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(echo_line) == 1 && running) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            if (timespec_subtract(&ts_end, &ts_start) > TIMEOUT_US) {
                fprintf(stderr, "Echo did not stop\n");
                break;
            }
        }

        if (!running) break;

        // Calculate the duration
        long duration = timespec_subtract(&ts_end, &ts_start);

        // Calculate distance in cm
        double distance = (duration * 34000.0) / 2.0 / 1000000.0;

        printf("Distance: %.2f cm\n", distance);

        // Sleep for 1 second
        sleep(1);
    }

    // Release the lines and close the chip
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

// Helper function to subtract two timespecs
