#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_RETRIES 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_dht11(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line;
    int ret, i, bit_count = 0;
    uint8_t data[5] = {0};
    uint32_t pulse_lengths[40] = {0};

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "dht11", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_set_value(line, 0);
    usleep(18000); // 18 ms low
    gpiod_line_set_value(line, 1);
    usleep(40); // 40 us high

    ret = gpiod_line_request_input(line, "dht11");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        return -1;
    }

    for (i = 0; i < 40; i++) {
        int level = gpiod_line_get_value(line);
        if (level < 0) {
            perror("Failed to read GPIO line");
            gpiod_line_release(line);
            return -1;
        }

        while (gpiod_line_get_value(line) == level) {
            if (!running) {
                gpiod_line_release(line);
                return -1;
            }
            usleep(1);
            pulse_lengths[i]++;
        }
    }

    gpiod_line_release(line);

    for (i = 0; i < 40; i += 2) {
        data[i / 8] <<= 1;
        if (pulse_lengths[i + 1] > 70) {
            data[i / 8] |= 1;
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    printf("Temperature: %d.%d C, Humidity: %d.%d %%\n", data[2], data[3], data[0], data[1]);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret, retries = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    while (retries < MAX_RETRIES && running) {
        ret = read_dht11(chip, DHT11_PIN);
        if (ret == 0) {
            break;
        }
        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Device not responding after %d retries\n", MAX_RETRIES);
            ret = EXIT_FAILURE;
        }
    }

    gpiod_chip_close(chip);
    return ret;
}

