#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_2  2
#define GPIO_3  3
#define GPIO_18 18

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIOs as PWM outputs
    if (gpioSetMode(GPIO_2, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_3, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 1000 Hz
    if (gpioSetPWMfrequency(GPIO_2, 1000) < 0 ||
        gpioSetPWMfrequency(GPIO_3, 1000) < 0 ||
