        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Combine the bytes into a single 16-bit value
    result = (buffer[0] << 8) | buffer[1];

    // Print the result
    printf("OPT3001 Reading: 0x%04X\n", result);

    // Close the I2C bus
    close(i2c_fd);

