#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_4   4
#define GPIO_12  12
#define GPIO_18  18

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIOs as PWM outputs
    if (gpioSetMode(GPIO_4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_12, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_12);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 1kHz
    if (gpioSetPWMfrequency(GPIO_4, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_12, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_12);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_18, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Set different duty cycles
        gpioPWM(GPIO_4, 512);  // 50% duty cycle
        gpioPWM(GPIO_12, 768); // 75% duty cycle
        gpioPWM(GPIO_18, 256); // 25% duty cycle

        printf("GPIO %d: 50%%, GPIO %d: 75%%, GPIO %d: 25%%\n", GPIO_4, GPIO_12, GPIO_18);

        sleep(1);

        gpioPWM(GPIO_4, 768);  // 75% duty cycle
        gpioPWM(GPIO_12, 256); // 25% duty cycle
        gpioPWM(GPIO_18, 512); // 50% duty cycle

        printf("GPIO %d: 75%%, GPIO %d: 25%%, GPIO %d: 50%%\n", GPIO_4, GPIO_12, GPIO_18);

        sleep(1);
    }

    // Clean up
    gpioPWM(GPIO_4, 0);
    gpioPWM(GPIO_12, 0);
    gpioPWM(GPIO_18, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

