#define READ_TIMEOUT 5

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_temperature(const char *device_path) {
    int fd = open(device_path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open device");
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read == -1) {
        perror("Failed to read from device");
        return -1;
    }

    buffer[bytes_read] = '\0';

    // Check if the reading is valid
    const char *valid_str = "YES";
    if (strstr(buffer, valid_str) == NULL) {
        fprintf(stderr, "Invalid reading\n");
        return -1;
    }

    // Extract the temperature value
    const char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature not found in reading\n");
        return -1;
    }

    temp_str += 2; // Move past "t="
    int temperature = atoi(temp_str);

    printf("Temperature: %d.%03d C\n", temperature / 1000, temperature % 1000);

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        glob_t glob_result;
        int ret = glob(W1_DEVICE_PATH, GLOB_TILDE, NULL, &glob_result);
        if (ret != 0) {
            fprintf(stderr, "No DS18B20 device found\n");
            exit(EXIT_FAILURE);
        }

        if (glob_result.gl_pathc == 0) {
            fprintf(stderr, "No DS18B20 device found\n");
            globfree(&glob_result);
            exit(EXIT_FAILURE);
        }

        for (size_t i = 0; i < glob_result.gl_pathc; i++) {
            if (read_temperature(glob_result.gl_pathv[i]) != 0) {
                fprintf(stderr, "Error reading temperature from device\n");
                exit(EXIT_FAILURE);
            }
        }

        globfree(&glob_result);
        sleep(READ_TIMEOUT);
    }

    return 0;
}

