#define HTU21D_I2C_ADDRESS 0x40
#define TRIGGER_TEMP_MEASURE_NO_HOLD 0xF3
#define TRIGGER_HUM_MEASURE_NO_HOLD 0xF5

int i2c_fd = -1;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    if (read(fd, buffer, 3) != 3) {
        perror("Failed to read from I2C");
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

float convert_temp(uint16_t raw_temp) {
    return -46.85 + 175.72 * raw_temp / 65536.0;
}

float convert_humidity(uint16_t raw_hum) {
    return -6.0 + 125.0 * raw_hum / 65536.0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        uint16_t raw_temp, raw_hum;
        float temp, humidity;

        if (read_i2c_register(i2c_fd, TRIGGER_TEMP_MEASURE_NO_HOLD, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (read_i2c_register(i2c_fd, TRIGGER_HUM_MEASURE_NO_HOLD, &raw_hum) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        temp = convert_temp(raw_temp);
        humidity = convert_humidity(raw_hum);

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        sleep(60);
    }

    cleanup();
    return 0;
}

