#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_I2C_ADDRESS 0x53
#define ADXL345_REG_DATAX0 0x32

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, ADXL345_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return EXIT_FAILURE;
    }

    // Set up signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        close(file);
        return EXIT_FAILURE;
    }

    // Enable measurements
    unsigned char write_buffer[2] = {0x2D, 0x08}; // POWER_CTL register, measure mode
    if (write(file, write_buffer, 2) != 2) {
        perror("Failed to write to ADXL345");
        close(file);
        return EXIT_FAILURE;
    }

    while (running) {
        unsigned char read_buffer[6];
        unsigned char reg = ADXL345_REG_DATAX0;

        if (write(file, &reg, 1) != 1) {
            perror("Failed to write register address");
            break;
        }

        if (read(file, read_buffer, 6) != 6) {
            perror("Failed to read from ADXL345");
            break;
        }

        int x = (read_buffer[1] << 8) | read_buffer[0];
        int y = (read_buffer[3] << 8) | read_buffer[2];
        int z = (read_buffer[5] << 8) | read_buffer[4];

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        usleep(100000); // Sleep for 0.1 seconds
    }

    close(file);
    return EXIT_SUCCESS;
}

