#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIOs as PWM outputs
    if (gpioSetMode(GPIO_17, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_22, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency (e.g., 1000 Hz)
    if (gpioSetPWMfrequency(GPIO_17, 1000) < 0 ||
        gpioSetPWMfrequency(GPIO_22, 1000) < 0 ||
        gpioSetPWMfrequency(GPIO_27, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Set PWM duty cycle (0-100%)
        gpioPWM(GPIO_17, 500); // 50% duty cycle
        gpioPWM(GPIO_22, 750); // 75% duty cycle
        gpioPWM(GPIO_27, 250); // 25% duty cycle

        printf("GPIO 17: 50%%, GPIO 22: 75%%, GPIO 27: 25%%\n");

        // Sleep for 0.5 seconds
        gpioDelay(500000);

        // Reset PWM duty cycle to 0%
        gpioPWM(GPIO_17, 0);
        gpioPWM(GPIO_22, 0);
        gpioPWM(GPIO_27, 0);

        printf("GPIO 17: 0%%, GPIO 22: 0%%, GPIO 27: 0%%\n");

        // Sleep for 0.5 seconds
        gpioDelay(500000);
    }

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

