#define GPIO_PIN 18
#define INTERVAL_US 20000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set GPIO pin as PWM output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 1000 Hz
    if (gpioSetPWMfrequency(GPIO_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        for (int duty_cycle = 0; duty_cycle <= 100; duty_cycle++) {
            if (!running) break;
            gpioPWM(GPIO_PIN, duty_cycle * 10000); // 0-100% duty cycle
            printf("Duty Cycle: %d%%\n", duty_cycle);
            gpioDelay(INTERVAL_US);
        }
        for (int duty_cycle = 100; duty_cycle >= 0; duty_cycle--) {
            if (!running) break;
            gpioPWM(GPIO_PIN, duty_cycle * 10000); // 100-0% duty cycle
            printf("Duty Cycle: %d%%\n", duty_cycle);
            gpioDelay(INTERVAL_US);
        }
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0); // Turn off PWM
    gpioTerminate();

