    // Set up signal handler for graceful exit
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the I2C bus
    if ((i2c_fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    // Specify the address of the TCS34725
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Enable the device
    buffer[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buffer[1] = TCS34725_ENABLE_AIEN | TCS34725_ENABLE_PON;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to the i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read the color data
        buffer[0] = TCS34725_COMMAND_BIT | TCS34725_CDATAL;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c device");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        if (read(i2c_fd, buffer, 8) != 8) {
            perror("Failed to read from the i2c device");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Extract the color values
        uint16_t clear = (buffer[1] << 8) | buffer[0];
        uint16_t red = (buffer[3] << 8) | buffer[2];
        uint16_t green = (buffer[5] << 8) | buffer[4];
        uint16_t blue = (buffer[7] << 8) | buffer[6];

        // Print the readings
        printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

        // Wait for 0.2 seconds
        usleep(200000);
    }

    // Close the I2C bus
    close(i2c_fd);
    return EXIT_SUCCESS;
}

