#include <pigpio.h>

#define GPIO_PIN_8  8
#define GPIO_PIN_9  9
#define GPIO_PIN_11 11
#define GPIO_PIN_18 18

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIO pins as PWM outputs
    int pins[] = {GPIO_PIN_8, GPIO_PIN_9, GPIO_PIN_11, GPIO_PIN_18};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) { // 1kHz frequency
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (running) {
        for (int i = 0; i < 4; i++) {
            for (int duty_cycle = 0; duty_cycle <= 100; duty_cycle += 10) {
                gpioPWM(pins[i], duty_cycle * 10000); // 0-100% duty cycle
                printf("GPIO %d: %d%%\n", pins[i], duty_cycle);
                gpioDelay(100000); // 100ms delay
            }
            for (int duty_cycle = 100; duty_cycle >= 0; duty_cycle -= 10) {
                gpioPWM(pins[i], duty_cycle * 10000); // 100-0% duty cycle
                printf("GPIO %d: %d%%\n", pins[i], duty_cycle);
                gpioDelay(100000); // 100ms delay
            }
        }
        gpioDelay(1000000); // 1s delay between cycles
    }

    // Clean up
    for (int i = 0; i < 4; i++) {
        gpioPWM(pins[i], 0); // Turn off PWM
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
