#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define BUFFER_COUNT 4

static int fd = -1;
static struct v4l2_buffer buf[BUFFER_COUNT];
static void *buffers[BUFFER_COUNT];

static void cleanup() {
    if (fd != -1) {
        for (int i = 0; i < BUFFER_COUNT; ++i) {
            if (buffers[i]) {
                munmap(buffers[i], buf[i].length);
            }
        }
        close(fd);
    }
}

static void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        struct v4l2_requestbuffers req;
        req.count = BUFFER_COUNT;
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
            perror("Failed to request buffers");
            cleanup();
            return EXIT_FAILURE;
        }

        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf[i]) == -1) {
            perror("Failed to query buffer");
            cleanup();
            return EXIT_FAILURE;
        }

        buffers[i] = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (ioctl(fd, VIDIOC_QBUF, &buf[i]) == -1) {
            perror("Failed to queue buffer");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start streaming");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv = {0};
        tv.tv_sec = 0;
        tv.tv_usec = 50000; // 0.05 seconds

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            perror("Failed in select");
            break;
        } else if (r == 0) {
            continue;
        }

        struct v4l2_buffer v4l2_buf;
        v4l2_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        v4l2_buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &v4l2_buf) == -1) {
            perror("Failed to dequeue buffer");
            break;
        }

        FILE *file = fopen("image.jpg", "wb");
        if (!file) {
            perror("Failed to open file for writing");
            ioctl(fd, VIDIOC_QBUF, &v4l2_buf);
            break;
        }

        fwrite(buffers[v4l2_buf.index], 1, v4l2_buf.bytesused, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &v4l2_buf) == -1) {
            perror("Failed to requeue buffer");
            break;
        }

        usleep(50000); // 0.05 seconds
    }

    ioctl(fd, VIDIOC_STREAMOFF, &type);
    cleanup();
    return EXIT_SUCCESS;
}

