                           ADS1115_REG_CONFIG_CPOL_ACTVLOW |
                           ADS1115_REG_CONFIG_CLAT_NONLAT |
                           ADS1115_REG_CONFIG_BADC_NORMAL |
                           ADS1115_REG_CONFIG_SADC_NORMAL |
                           ADS1115_REG_CONFIG_OSR_16;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(i2c_device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure the ADS1115
    unsigned char config_bytes[3];
    config_bytes[0] = ADS1115_REG_POINTER_CONFIG;
    config_bytes[1] = (config >> 8) & 0xFF;
    config_bytes[2] = config & 0xFF;

    if (write(i2c_fd, config_bytes, 3) != 3) {
        perror("Failed to write to the i2c device");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read conversion result
        unsigned char read_buffer[2];
        if (read(i2c_fd, read_buffer, 2) != 2) {
            perror("Failed to read from the i2c device");
            cleanup();
            exit(EXIT_FAILURE);
        }

        int adc_value = ((read_buffer[0] << 8) | read_buffer[1]) >> 4;
        printf("ADC Value: %d\n", adc_value);

        // Wait for 0.2 seconds
        usleep(200000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 4
#define INTERVAL 60

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto exit;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        goto exit;
    }

    // Request the line as an output
    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        goto exit;
    }

    while (running) {
        // Toggle the GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to get GPIO line value");
            break;
        }
        value = !value;
        if (gpiod_line_set_value(line, value) < 0) {
            perror("Failed to set GPIO line value");
            break;
        }

        // Report the state
        printf("GPIO %d set to %d\n", GPIO_LINE, value);

        // Sleep for the specified interval
        sleep(INTERVAL);
    }

    ret = EXIT_SUCCESS;

exit:
    // Release the GPIO line
    if (line)
        gpiod_line_release(line);

    // Close the GPIO chip
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

