#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LCD_ADDRESS 0x27

// Commands
#define LCD_CLEAR 0x01
#define LCD_HOME 0x02
#define LCD_ENTRY_MODE_SET 0x04
#define LCD_DISPLAY_CONTROL 0x08
#define LCD_CURSOR_SHIFT 0x10
#define LCD_FUNCTION_SET 0x20
#define LCD_SET_CGRAM_ADDR 0x40
#define LCD_SET_DDRAM_ADDR 0x80

// Flags for display entry mode
#define LCD_ENTRY_RIGHT 0x00
#define LCD_ENTRY_LEFT 0x02
#define LCD_ENTRY_SHIFT_INCREMENT 0x01
#define LCD_ENTRY_SHIFT_DECREMENT 0x00

// Flags for display on/off control
#define LCD_DISPLAY_ON 0x04
#define LCD_DISPLAY_OFF 0x00
#define LCD_CURSOR_ON 0x02
#define LCD_CURSOR_OFF 0x00
#define LCD_BLINK_ON 0x01
#define LCD_BLINK_OFF 0x00

// Flags for display/cursor shift
#define LCD_DISPLAY_MOVE 0x08
#define LCD_CURSOR_MOVE 0x00
#define LCD_MOVE_RIGHT 0x04
#define LCD_MOVE_LEFT 0x00

// Flags for function set
#define LCD_8BIT_MODE 0x10
#define LCD_4BIT_MODE 0x00
#define LCD_2_LINE 0x08
#define LCD_1_LINE 0x00
#define LCD_5x10_DOTS 0x04
#define LCD_5x8_DOTS 0x00

int i2c_fd;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void signal_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

void i2c_write_byte(unsigned char byte) {
    unsigned char buffer[1] = {byte};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void lcd_send_command(unsigned char command) {
    i2c_write_byte(command & 0xF0);
    i2c_write_byte((command << 4) & 0xF0);
    usleep(1000);
}

void lcd_send_data(unsigned char data) {
    i2c_write_byte(data | 0x0F);
    i2c_write_byte(((data << 4) & 0xF0) | 0x0F);
    usleep(1000);
}

void lcd_init() {
    lcd_send_command(LCD_FUNCTION_SET | LCD_4BIT_MODE | LCD_2_LINE | LCD_5x8_DOTS);
    lcd_send_command(LCD_DISPLAY_CONTROL | LCD_DISPLAY_ON | LCD_CURSOR_OFF | LCD_BLINK_OFF);
    lcd_send_command(LCD_CLEAR);
    lcd_send_command(LCD_ENTRY_MODE_SET | LCD_ENTRY_LEFT | LCD_ENTRY_SHIFT_DECREMENT);
}

void lcd_print_string(const char *str) {
    while (*str) {
        lcd_send_data(*str++);
    }
}

int main() {
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    lcd_init();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        lcd_send_command(LCD_HOME);
        lcd_print_string("Hello, World!");
        sleep(10);
    }

    cleanup();
    return EXIT_SUCCESS;
}

