#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <paho_mqtt/MQTTClient.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "raspberry_pi_sensor"
#define MQTT_TOPIC "sensor/reading"
#define MQTT_QOS 1

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_sensor(struct gpiod_chip *chip, struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Failed to read sensor value");
        return -1;
    }
    // Example validity check: sensor should not return -1
    if (value == -1) {
        fprintf(stderr, "Invalid sensor reading\n");
        return -1;
    }
    return value;
}

void publish_sensor_reading(MQTTClient client, const char *topic, int reading) {
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", reading);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    MQTTClient_publishMessage(client, topic, &pubmsg, &token);
    MQTTClient_waitForCompletion(client, token, 1000);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "sensor_reader");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    while (running) {
        int reading = read_sensor(chip, line);
        if (reading >= 0) {
            publish_sensor_reading(client, MQTT_TOPIC, reading);
        }
        usleep(10000); // 10 ms
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

