#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define ECHO_PIN 17
#define TRIG_PIN 22
#define MAX_DISTANCE 400 // cm

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request TRIG line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("Failed to get TRIG line");
        goto close_chip;
    }
    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request TRIG line as output");
        goto release_trig;
    }

    // Request ECHO line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get ECHO line");
        goto release_trig;
    }
    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request ECHO line as input");
        goto release_echo;
    }

    while (running) {
        // Send trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo start
        struct timespec timeout = {0, 10000000}; // 10 ms timeout
        ret = gpiod_line_event_wait(echo_line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for echo start");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue;
        }

        // Measure echo duration
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1 && running) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) > 0 || (end.tv_nsec - start.tv_nsec) > 50000000) {
                fprintf(stderr, "Echo duration too long\n");
                break;
            }
        }
        if (!running) break;

        if (gpiod_line_get_value(echo_line) == 1) {
            fprintf(stderr, "Echo did not stop\n");
            continue;
        }

        long duration = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        double distance = duration / 58.0; // Speed of sound in air is approximately 343 m/s

        if (distance > 0 && distance <= MAX_DISTANCE) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
        }

        usleep(100000); // 0.1 second delay
    }

    // Clean up
release_echo:
    gpiod_line_release(echo_line);
release_trig:
    gpiod_line_release(trig_line);
close_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

