#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <mosquitto.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/reading"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_sensor_data(int i2c_fd) {
    unsigned char buffer[2];
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }
    int value = (buffer[0] << 8) | buffer[1];
    return value;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct mosquitto *mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create MQTT client\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = read_sensor_data(i2c_fd);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        char payload[16];
        snprintf(payload, sizeof(payload), "%d", sensor_value);

        if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false) != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Failed to publish MQTT message\n");
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        break; // Run once and exit
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000    // 0-1000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set GPIO pin as PWM output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency and range
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        for (int duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle++) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Applied PWM duty cycle: %d\n", duty_cycle);
            sleep(1);
        }
        for (int duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Applied PWM duty cycle: %d\n", duty_cycle);
            sleep(1);
        }
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

