            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            if (timespec_subtract(&ts_end, &ts_start) > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
        }

        if (!running) break;

        // Calculate distance
        long duration = timespec_subtract(&ts_end, &ts_start);
        float distance = (duration * 34300.0) / 2.0 / 1000000.0; // in cm

        printf("Distance: %.2f cm\n", distance);

        // Sleep for 0.2 seconds
        usleep(200000);
    }

    // Release resources
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

