    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENTID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        close(i2c_fd);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_READINGS && running; i++) {
        sleep(1); // Wait for conversion to complete
        lseek(i2c_fd, ADS1115_REG_CONVERSION, SEEK_SET);
        int value = ads1115_read_conversion(i2c_fd);
        if (value < 0) {
            break;
        }

        char payload[32];
        snprintf(payload, sizeof(payload), "{\"reading\": %d}", value);

        MQTTClient_message pubmsg = MQTTClient_message_initializer;
        pubmsg.payload = payload;
        pubmsg.payloadlen = strlen(payload);
        pubmsg.qos = 1;
        pubmsg.retained = 0;

        MQTTClient_deliveryToken token;
        MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
        MQTTClient_waitForCompletion(client, token, 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

