#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define BMP280_I2C_ADDRESS 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_MSB 0xF7

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    char *filename = "/dev/i2c-1";
    unsigned char buffer[3];
    int ret;

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((i2c_fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Specify the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Check if the device is present
    buffer[0] = BMP280_REG_ID;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to the i2c bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        perror("Failed to read from the i2c bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (buffer[0] != 0x58) { // BMP280 chip ID
        fprintf(stderr, "Device not found or incorrect chip ID\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read temperature
        buffer[0] = BMP280_REG_TEMP_MSB;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            break;
        }
        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read from the i2c bus");
            break;
        }
        int32_t temp_raw = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | buffer[2];

        // Read pressure
        buffer[0] = BMP280_REG_PRESS_MSB;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to the i2c bus");
            break;
        }
        if (read(i2c_fd, buffer, 3) != 3) {
            perror("Failed to read from the i2c bus");
            break;
        }
        int32_t press_raw = ((uint32_t)buffer[0] << 16) | ((uint32_t)buffer[1] << 8) | buffer[2];

        // Convert raw values to actual temperature and pressure
        // Simplified conversion for demonstration purposes
        float temperature = temp_raw / 100.0;
        float pressure = press_raw / 100.0;

        printf("Temperature: %.2f °C, Pressure: %.2f hPa\n", temperature, pressure);

        sleep(5);
    }

    // Close the I2C bus
    close(i2c_fd);

    return running ? EXIT_SUCCESS : EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000    // 0-1000

void cleanup(int sig) {
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main() {
    int result;

    // Initialize pigpio library
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialization failed: %d\n", result);
        return EXIT_FAILURE;
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Set GPIO pin as PWM output
    if ((result = gpioSetMode(GPIO_PIN, PI_OUTPUT)) != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", result);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Set PWM duty cycle to 50%
    int duty_cycle = 500; // 50% of PWM_RANGE
    gpioPWM(GPIO_PIN, duty_cycle);

    // Report the state
    printf("PWM output set on GPIO %d with duty cycle %d%%\n", GPIO_PIN, (duty_cycle * 100) / PWM_RANGE);

    // Wait for a short period to observe the output
    gpioDelay(2000000); // 2 seconds

    // Stop PWM and clean up
    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

