        perror("Failed to request GPIO 19 as output");
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Toggle GPIOs every 0.5 seconds
    while (running) {
        gpiod_line_set_value(line18, 1);
        gpiod_line_set_value(line19, 0);
        printf("GPIO 18: High, GPIO 19: Low\n");
        sleep(1);

        gpiod_line_set_value(line18, 0);
        gpiod_line_set_value(line19, 1);
        printf("GPIO 18: Low, GPIO 19: High\n");
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line18);
    gpiod_line_release(line19);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BUFFER_SIZE 1024

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int uart_fd;
    struct termios options;
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Configure the UART settings
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag &= ~PARENB; // No parity bit
    options.c_cflag &= ~CSTOPB; // One stop bit
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8; // 8 data bits
    options.c_cflag &= ~CRTSCTS; // Disable hardware flow control
    options.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Raw input
    options.c_iflag &= ~(IXON | IXOFF | IXANY); // Disable software flow control
    options.c_oflag &= ~OPOST; // Raw output
    tcsetattr(uart_fd, TCSANOW, &options);

    // Read data from the UART
    while (running) {
        bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("%s", buffer);
        } else if (bytes_read == 0) {
            // No data available, continue
        } else {
            perror("read");
            break;
        }
    }

    // Close the UART device
    close(uart_fd);

    return EXIT_SUCCESS;
}

