#define GPIO_PIN 18

void cleanup(int sig) {
    gpioTerminate();
    printf("Cleanup and exit\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);
    signal(SIGINT, cleanup);

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int frequency = 1000; // 1 kHz
    int duty_cycle = 500;  // 50% duty cycle

    if (gpioSetPWMfrequency(GPIO_PIN, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_PIN, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMdutycycle(GPIO_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output set on GPIO %d with frequency %d Hz and duty cycle %d%%\n",
           GPIO_PIN, frequency, (duty_cycle * 100) / 1000);

    // Sleep for 2 seconds to observe the PWM output
    gpioDelay(2000000);

    return EXIT_SUCCESS;
