#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONSUMER "dht22_reader"
#define GPIO_PIN 4

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_dht22(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line;
    int ret;
    uint8_t data[5] = {0};
    int bits[40] = {0};

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(18000);
    gpiod_line_set_value(line, 1);
    usleep(40);

    ret = gpiod_line_request_input(line, CONSUMER);
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        return -1;
    }

    // Wait for response
    ret = gpiod_line_get_value(line);
    if (ret != 0) {
        fprintf(stderr, "DHT22 did not respond\n");
        gpiod_line_release(line);
        return -1;
    }
    usleep(80);

    ret = gpiod_line_get_value(line);
    if (ret != 1) {
        fprintf(stderr, "DHT22 did not respond\n");
        gpiod_line_release(line);
        return -1;
    }
    usleep(80);

    // Read data
    for (int i = 0; i < 40; i++) {
        while (gpiod_line_get_value(line) == 0);
        usleep(30);
        bits[i] = gpiod_line_get_value(line);
        while (gpiod_line_get_value(line) == 1);
    }

    gpiod_line_release(line);

    // Convert data
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 8; j++) {
            data[i] <<= 1;
            data[i] |= bits[i * 8 + j];
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    printf("Temperature: %.1f C\n", (data[2] * 9.0 / 5.0) + 32);
    printf("Humidity: %.1f %%\n", data[0] + data[1] * 0.1);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ret = read_dht22(chip, GPIO_PIN);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from DHT22\n");
    }

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

