#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <mosquitto.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000

#define MCP3008_CHANNEL 0
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/reading"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_mcp3008(int spi_fd, uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid channel number\n");
        return -1;
    }

    uint8_t tx[] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

int main() {
    int spi_fd;
    mosquitto *mosq = NULL;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create MQTT client\n");
        close(spi_fd);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    // Connect to MQTT broker
    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        close(spi_fd);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    // Read sensor data
    int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        close(spi_fd);
        mosquitto_lib_cleanup();
        return EXIT_FAILURE;
    }

    // Publish sensor reading
    char payload[10];
    snprintf(payload, sizeof(payload), "%d", adc_value);
    mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);

    // Clean up
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    close(spi_fd);
    mosquitto_lib_cleanup();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void *start;
    size_t length;
};

static int xioctl(int fh, unsigned long request, void *arg) {
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main(int argc, char **argv) {
    struct v4l2_buffer buf;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct buffer *buffers;
    unsigned int n_buffers;
    int fd = -1;
    const char *dev_name = "/dev/video0";
    FILE *fp = NULL;

    if (argc > 1)
        dev_name = argv[1];

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (-1 == fd) {
        perror("Cannot open device");
        exit(EXIT_FAILURE);
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", dev_name);
            exit(EXIT_FAILURE);
        } else {
            perror("VIDIOC_QUERYCAP");
            exit(EXIT_FAILURE);
        }
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        exit(EXIT_FAILURE);
    }

    CLEAR(fmt);

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = 640;
    fmt.fmt.pix.height      = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field       = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    CLEAR(buf);

    buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory      = V4L2_MEMORY_MMAP;
    buf.index       = 0;

