#define BUFFER_COUNT 4

static int fd = -1;
static struct v4l2_buffer buf[BUFFER_COUNT];
static struct v4l2_requestbuffers req;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (fd != -1) {
        for (int i = 0; i < BUFFER_COUNT; i++) {
            ioctl(fd, VIDIOC_QBUF, &buf[i]);
        }
        ioctl(fd, VIDIOC_STREAMOFF, &req.type);
