void signal_handler(int signum) {
    running = 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = open(DEVICE, O_RDWR | O_NONBLOCK);
    if (fd == -1) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        cleanup();
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf[i], 0, sizeof(buf[i]));
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf[i]) == -1) {
            perror("Failed to query buffer");
            cleanup();
            return EXIT_FAILURE;
        }

        buf[i].m.offset = buf[i].m.offset;
        buf[i].length = buf[i].length;
        buf[i].m.userptr = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (buf[i].m.userptr == MAP_FAILED) {
            perror("Failed to mmap buffer");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (unsigned int i = 0; i < req.count; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &buf[i]) == -1) {
            perror("Failed to queue buffer");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Failed to start streaming");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = 100000; // 0.1 seconds

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("Select failed");
            break;
        } else if (r == 0) {
            continue; // Timeout, try again
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf[0]) == -1) {
            if (errno == EAGAIN || errno == EIO) continue;
            perror("Failed to dequeue buffer");
            break;
        }

        FILE *file = fopen("image.jpg", "wb");
        if (!file) {
            perror("Failed to open file");
            ioctl(fd, VIDIOC_QBUF, &buf[0]);
            continue;
        }

        fwrite(buf[0].m.userptr, 1, buf[0].bytesused, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf[0]) == -1) {
            perror("Failed to requeue buffer");
            break;
        }

        usleep(100000); // Sleep for 0.1 seconds
    }

    cleanup();
    return EXIT_SUCCESS;
}

