    gpiod_line_set_value(trig_line, 0);

    // Wait for echo
    struct timespec ts_start, ts_end;
    if (gpiod_line_event_wait(echo_line, NULL) < 0) {
        perror("gpiod_line_event_wait");
        goto cleanup;
    }

    if (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(echo_line) == 1 && running) {
            if (clock_gettime(CLOCK_MONOTONIC, &ts_end) < 0) {
                perror("clock_gettime");
                goto cleanup;
            }
            if ((ts_end.tv_sec - ts_start.tv_sec) * 1e6 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1e3 > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo\n");
                goto cleanup;
            }
        }
    } else {
        fprintf(stderr, "Echo did not start\n");
        goto cleanup;
    }

    // Calculate distance
    long duration_us = (ts_end.tv_sec - ts_start.tv_sec) * 1e6 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1e3;
    double distance_cm = duration_us * 0.034 / 2;

    printf("Distance: %.2f cm\n", distance_cm);

cleanup:
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    return running ? EXIT_SUCCESS : EXIT_FAILURE;
}

