#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

volatile sig_atomic_t running = 1;

void cleanup(int sig) {
    running = 0;
}

int main() {
    int fd;
    char *filename = "/dev/i2c-1";
    unsigned char buffer[6];
    short accel_x, accel_y, accel_z;

    // Register signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Select the MPU6050 device
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read accelerometer data
        if (write(fd, &ACCEL_XOUT_H, 1) != 1) {
            perror("Failed to write to the i2c bus");
            close(fd);
            exit(EXIT_FAILURE);
        }
        if (read(fd, buffer, 6) != 6) {
            perror("Failed to read from the i2c bus");
            close(fd);
            exit(EXIT_FAILURE);
        }

        // Convert data to short
        accel_x = (buffer[0] << 8) | buffer[1];
        accel_y = (buffer[2] << 8) | buffer[3];
        accel_z = (buffer[4] << 8) | buffer[5];

        // Print the results
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Close the I2C bus
    close(fd);
    return EXIT_SUCCESS;
}

