static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    int pins[] = GPIO_PINS;
    int num_pins = sizeof(pins) / sizeof(pins[0]);
    int i, cycle;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    lines = gpiod_chip_get_lines(chip, pins, num_pins);
    if (!lines) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_bulk_output(&lines, CONSUMER)) {
        perror("Failed to request GPIO lines as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    for (cycle = 0; cycle < 3 && running; cycle++) {
        for (i = 0; i < num_pins && running; i++) {
            if (gpiod_line_set_value(gpiod_line_bulk_get_line(&lines, i), 1)) {
                perror("Failed to set GPIO line value");
                break;
            }
            printf("GPIO %d set to HIGH\n", pins[i]);
        }

        sleep(5);

        for (i = 0; i < num_pins && running; i++) {
            if (gpiod_line_set_value(gpiod_line_bulk_get_line(&lines, i), 0)) {
                perror("Failed to set GPIO line value");
                break;
            }
            printf("GPIO %d set to LOW\n", pins[i]);
        }

        sleep(5);
    }

    // Release resources
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

