#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SHT31_ADDRESS 0x44
#define CMD_MEASURE_HIGH_PRECISION 0x2400

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int i2c_fd;
    struct sigaction sa;
    uint8_t cmd[2] = {CMD_MEASURE_HIGH_PRECISION >> 8, CMD_MEASURE_HIGH_PRECISION & 0xFF};
    uint8_t data[6];
    float temperature, humidity;

    // Set up signal handler for graceful exit
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(EXIT_FAILURE);
    }

    // Specify the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT31_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Send the measurement command
        if (write(i2c_fd, cmd, 2) != 2) {
            perror("Failed to send measurement command");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Wait for the measurement to complete (typically 15ms)
        usleep(15000);

        // Read the measurement result
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read measurement result");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Check CRC (simple implementation, assuming CRC is correct)
        // In a real application, you should implement CRC checking here

        // Convert raw data to temperature and humidity
        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t humid_raw = (data[3] << 8) | data[4];
        temperature = -45 + 175 * (temp_raw / 65535.0);
        humidity = 100 * (humid_raw / 65535.0);

        // Print the results
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the I2C bus
    close(i2c_fd);
    return EXIT_SUCCESS;
}

