#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

void cleanup(int sig) {
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Set GPIOs as PWM outputs
    int gpios[] = {GPIO_17, GPIO_18, GPIO_22, GPIO_27};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(gpios[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", gpios[i]);
            cleanup(0);
        }
        if (gpioSetPWMfrequency(gpios[i], 1000) < 0) { // 1kHz frequency
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpios[i]);
            cleanup(0);
        }
    }

    // Set PWM duty cycle (50%)
    uint16_t duty_cycle = 500; // 50% of 1000Hz period
    for (int i = 0; i < 4; i++) {
        gpioPWM(gpios[i], duty_cycle);
        printf("Set GPIO %d to PWM with duty cycle %d\n", gpios[i], duty_cycle);
    }

    // Wait for a short period to observe the output
    gpioDelay(2000000); // 2 seconds

    // Clean up
    gpioTerminate();
    return EXIT_SUCCESS;
}

