#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 18
#define CYCLES 3
#define DELAY_US 5000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Register signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Define RGB color values
    int colors[][3] = {
        {255, 0, 0},   // Red
        {0, 255, 0},   // Green
        {0, 0, 255}    // Blue
    };

    // Main loop
    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        for (int i = 0; i < 3 && running; i++) {
            // Set the color
            gpioPWM(LED_PIN, colors[i][0]); // Assuming PWM for brightness control
            gpioDelay(DELAY_US);

            // Clear the color
            gpioPWM(LED_PIN, 0);
            gpioDelay(DELAY_US);
        }
    }

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

