    int ret = glob(W1_DEVICE_PATH, GLOB_TILDE, NULL, &glob_result);
    if (ret != 0 || glob_result.gl_pathc == 0) {
        fprintf(stderr, "Error: DS18B20 device not found.\n");
        globfree(&glob_result);
        return EXIT_FAILURE;
