        int fd = open(device_path, O_RDONLY);
        if (fd == -1) {
            perror("Error opening device file");
            return EXIT_FAILURE;
        }

        char buffer[256];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        close(fd);

        if (bytes_read == -1) {
            perror("Error reading from device file");
            return EXIT_FAILURE;
        }

        buffer[bytes_read] = '\0';

        // Find the line with "t="
        char *line = strstr(buffer, "t=");
        if (line == NULL) {
