    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines
    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request trig line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo to start
        struct timespec timeout = {0, 10000}; // 10 ms timeout
        ret = gpiod_line_event_wait(echo_line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for echo start");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Echo did not start within timeout\n");
            continue;
        }

        // Measure the duration of the echo pulse
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(echo_line, &event);
        if (ret < 0) {
            perror("Failed to read echo event");
            break;
        }

        struct timespec start = event.ts;
        while (gpiod_line_get_value(echo_line) == 1 && running) {
            // Busy wait for echo to end
        }

        struct timespec end;
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the duration in microseconds
        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Calculate distance in cm
        float distance = duration * 0.034 / 2;

        // Ensure distance is within the documented range
        if (distance > MAX_DISTANCE) {
            distance = MAX_DISTANCE;
        }

        printf("Distance: %.2f cm\n", distance);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Release resources
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

