#define CYCLES 3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_dht22(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line;
    int ret;
    uint8_t data[5] = {0};
    int bits_read = 0;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_input(line, CONSUMER);
    if (ret < 0) {
        perror("Failed to request input");
        gpiod_line_release(line);
        return -1;
    }

    // Wait for the sensor to pull the line low
    while (gpiod_line_get_value(line) == 1 && running) {
        usleep(1000);
    }
    if (!running) {
        gpiod_line_release(line);
        return -1;
    }

    // Wait for the sensor to pull the line high
    while (gpiod_line_get_value(line) == 0 && running) {
        usleep(1000);
    }
    if (!running) {
        gpiod_line_release(line);
        return -1;
    }

    // Read the 40 bits of data
    for (int i = 0; i < 40 && running; i++) {
        // Wait for the line to go low
        while (gpiod_line_get_value(line) == 1 && running) {
            usleep(1000);
        }
        if (!running) {
            gpiod_line_release(line);
            return -1;
        }

        // Measure the duration of the high pulse
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0 && running) {
            // Do nothing
        }
        if (!running) {
            gpiod_line_release(line);
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);

        long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration > 70) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
        bits_read++;
    }

    gpiod_line_release(line);

    if (bits_read != 40 || !running) {
        return -1;
    }

    // Validate the checksum
    uint8_t checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < CYCLES && running; i++) {
        ret = read_dht22(chip, GPIO_PIN);
        if (ret == 0) {
            printf("Cycle %d: Sensor data read successfully\n", i + 1);
        } else {
            printf("Cycle %d: Failed to read sensor data\n", i + 1);
            break;
        }
        sleep(2); // Wait for at least 2 seconds between readings
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

