    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk bulk;
    int ret;
    unsigned int i, j;

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request lines
    const unsigned int gpios[NUM_GPIOS] = GPIOS;
    ret = gpiod_chip_get_lines(chip, gpios, NUM_GPIOS, &bulk);
    if (ret < 0) {
        perror("gpiod_chip_get_lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines as outputs
    ret = gpiod_line_request_bulk_output(&bulk, CONSUMER);
    if (ret < 0) {
        perror("gpiod_line_request_bulk_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Toggle GPIOs
    for (i = 0; i < CYCLES && running; i++) {
        for (j = 0; j < NUM_GPIOS; j++) {
            ret = gpiod_line_set_value(bulk.lines[j], (i + j) % 2);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
        }
        if (!running) break;
        printf("Cycle %u: GPIOs set to %d\n", i + 1, (i + j) % 2);
        usleep(INTERVAL_US);
    }

    // Release lines
    gpiod_line_release_bulk(&bulk);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

