#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_GPIO_PINS 4
#define PINS[NUM_GPIO_PINS] {4, 17, 18, 27}
#define CYCLES 5
#define INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int pins[NUM_GPIO_PINS] = PINS;
    int cycle = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins for PWM output
    for (int i = 0; i < NUM_GPIO_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) { // 1kHz frequency
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running && cycle < CYCLES) {
        printf("Cycle %d starting\n", cycle + 1);

        // Increase duty cycle from 0% to 100%
        for (int duty = 0; duty <= 100; duty++) {
            for (int i = 0; i < NUM_GPIO_PINS; i++) {
                gpioPWM(pins[i], duty * 10000); // 10000 is the range for 100%
            }
            gpioDelay(10000); // 10ms delay
        }

        // Decrease duty cycle from 100% to 0%
        for (int duty = 100; duty >= 0; duty--) {
            for (int i = 0; i < NUM_GPIO_PINS; i++) {
                gpioPWM(pins[i], duty * 10000);
            }
            gpioDelay(10000); // 10ms delay
        }

        cycle++;
        if (cycle < CYCLES) {
            gpioDelay(INTERVAL * 1000000); // Wait for 60 seconds between cycles
        }
    }

    // Stop PWM and clean up
    for (int i = 0; i < NUM_GPIO_PINS; i++) {
        gpioPWM(pins[i], 0);
        gpioSetMode(pins[i], PI_INPUT);
    }

    gpioTerminate();
    printf("Program terminated\n");
    return EXIT_SUCCESS;
}

