#define PINS_COUNT 6
const int pins[PINS_COUNT] = {17, 18, 22, 23, 24, 25};
volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < PINS_COUNT; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            goto cleanup;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) { // 1kHz frequency
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        for (int i = 0; i < PINS_COUNT; i++) {
            int duty_cycle = (i * 100 / PINS_COUNT) * 10000; // 0% to 100%
