#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define DHT22_GPIO_PIN 4
#define CYCLES 3
#define INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int read_dht22(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line;
    int ret;
    uint8_t data[5] = {0};
    int bits[40] = {0};

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        return -1;
    }

    // Send start signal
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);

    ret = gpiod_line_request_input(line, "dht22");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        return -1;
    }

    // Wait for response
    struct timespec timeout = {0, 100000}; // 100us
    ret = gpiod_line_event_wait(line, &timeout);
    if (ret < 0) {
        perror("Failed to wait for line event");
        gpiod_line_release(line);
        return -1;
    }

    // Read data bits
    for (int i = 0; i < 40; i++) {
        struct timespec bit_timeout = {0, 70000}; // 70us
        ret = gpiod_line_event_wait(line, &bit_timeout);
        if (ret < 0) {
            perror("Failed to wait for bit event");
            gpiod_line_release(line);
            return -1;
        }
        bits[i] = gpiod_line_get_value(line);
        struct timespec bit_delay = {0, 50000}; // 50us
        nanosleep(&bit_delay, NULL);
    }

    // Convert bits to bytes
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 8; j++) {
            data[i] <<= 1;
            data[i] |= bits[i * 8 + j];
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum error\n");
        gpiod_line_release(line);
        return -1;
    }

    printf("Temperature: %.1f C, Humidity: %.1f%%\n",
           (data[2] * 256 + data[3]) / 10.0,
           (data[0] * 256 + data[1]) / 10.0);

    gpiod_line_release(line);
    return 0;
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open_by_label("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < CYCLES && running; i++) {
        ret = read_dht22(chip, DHT22_GPIO_PIN);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from DHT22\n");
        }
        sleep(INTERVAL);
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

