    // Configure lines as outputs
    ret = gpiod_line_request_bulk_output(&bulk, CONSUMER);
    if (ret < 0) {
        perror("Failed to request GPIO lines as outputs");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop: 3 cycles of setting each pin high and low
    for (int cycle = 0; cycle < 3 && running; cycle++) {
        for (i = 0; i < NUM_PINS && running; i++) {
            printf("Setting GPIO %d high\n", pins[i]);
            ret = gpiod_line_set_value(bulk.lines[i], 1);
            if (ret < 0) {
