    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIOs as PWM outputs
    if (gpioSetMode(GPIO_17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 1kHz
    if (gpioSetPWMfrequency(GPIO_17, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_18, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_18);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_27, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Set different duty cycles
        gpioPWM(GPIO_17, 500); // 50% duty cycle
        gpioPWM(GPIO_18, 750); // 75% duty cycle
        gpioPWM(GPIO_27, 250); // 25% duty cycle

        printf("GPIO %d: 50%%\n", GPIO_17);
        printf("GPIO %d: 75%%\n", GPIO_18);
        printf("GPIO %d: 25%%\n", GPIO_27);

        sleep(1);

        // Reset duty cycles
        gpioPWM(GPIO_17, 0);
        gpioPWM(GPIO_18, 0);
        gpioPWM(GPIO_27, 0);

        printf("GPIO %d: 0%%\n", GPIO_17);
        printf("GPIO %d: 0%%\n", GPIO_18);
        printf("GPIO %d: 0%%\n", GPIO_27);

        sleep(1);
    }

    // Clean up
    gpioPWM(GPIO_17, 0);
    gpioPWM(GPIO_18, 0);
    gpioPWM(GPIO_27, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

