void cleanup(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup(0);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set bits per word");
        cleanup(0);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set max speed");
        cleanup(0);
    }

    uint8_t tx[] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(rx),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer data");
        cleanup(0);
    }

    close(spi_fd);

    uint32_t raw_data = (rx[0] << 24) | (rx[1] << 16) | (rx[2] << 8) | rx[3];
    int16_t temp_raw = (raw_data >> 18) & 0x3FFF;
    float temperature = temp_raw * 0.25;

    printf("Temperature: %.2f°C\n", temperature);

    return EXIT_SUCCESS;
}

