        int32_t humidity = ((int32_t)humidity_msb << 8) | (int32_t)humidity_lsb;

        printf("Reading %d:\n", i + 1);
        printf("Pressure: %d Pa\n", pressure);
        printf("Temperature: %d *C\n", temperature);
        printf("Humidity: %d %%\n", humidity);

