#include <signal.h>
#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define BUFFER_SIZE 256
#define READ_TIMEOUT 100000 // 100 ms

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int uart_fd;
    struct termios options;
    char buffer[BUFFER_SIZE];
    fd_set read_fds;
    struct timeval timeout;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Configure the UART settings
    if (tcgetattr(uart_fd, &options) != 0) {
        perror("tcgetattr");
        close(uart_fd);
        exit(EXIT_FAILURE);
    }

    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(uart_fd, TCSANOW, &options) != 0) {
        perror("tcsetattr");
        close(uart_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = 0;
        timeout.tv_usec = READ_TIMEOUT;

        int select_result = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (select_result == -1) {
            perror("select");
            break;
        } else if (select_result == 0) {
            fprintf(stderr, "Timeout: Device did not respond.\n");
            break;
        }

        ssize_t bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read == -1) {
            perror("read");
            break;
        } else if (bytes_read == 0) {
            fprintf(stderr, "Device disconnected.\n");
            break;
        }

        buffer[bytes_read] = '\0';
        printf("%s", buffer);

        usleep(100000); // 100 ms delay
    }

    // Clean up
    tcsetattr(uart_fd, TCSANOW, &options);
    close(uart_fd);

    return EXIT_SUCCESS;
}

