        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for the echo to start
        struct timespec ts_start, ts_end;
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(echo_line) == 0 && running) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            if (timespec_diff_us(&ts_end, &ts_start) > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
        }

        if (!running) break;

        // Wait for the echo to stop
        clock_gettime(CLOCK_MONOTONIC, &ts_start);
        while (gpiod_line_get_value(echo_line) == 1 && running) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            if (timespec_diff_us(&ts_end, &ts_start) > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
        }

        if (!running) break;

        if (timespec_diff_us(&ts_end, &ts_start) <= TIMEOUT_US) {
            long duration_us = timespec_diff_us(&ts_end, &ts_start);
            double distance_cm = duration_us * 0.034 / 2.0;
            printf("Distance: %.2f cm\n", distance_cm);
        }

        usleep(500000); // Sleep for 0.5 seconds
    }

    // Release resources
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

long timespec_diff_us(struct timespec *a, struct timespec *b) {
    return (a->tv_sec - b->tv_sec) * 1000000 + (a->tv_nsec - b->tv_nsec) / 1000;
}

