        for (i = 0; i < NUM_PINS; i++) {
            int value = i % 2; // Toggle between 0 and 1
            ret = gpiod_line_set_value(lines.lines[i], value);
            if (ret < 0) {
                perror("Failed to set GPIO line value");
                goto cleanup;
            }
