#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 22
#define INTERVAL_US 10000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIO pins as PWM outputs
    if (gpioSetMode(GPIO_PIN_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Start PWM on both GPIOs with frequency 1000 Hz
    if (gpioSetPWMfrequency(GPIO_PIN_1, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_PIN_2, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GPIO_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    while (running) {
        // Toggle duty cycle between 0% and 50%
        gpioPWM(GPIO_PIN_1, duty_cycle);
        gpioPWM(GPIO_PIN_2, duty_cycle);

        printf("GPIO %d: %d%%, GPIO %d: %d%%\n", GPIO_PIN_1, duty_cycle, GPIO_PIN_2, duty_cycle);

        // Toggle duty cycle
        duty_cycle = (duty_cycle == 0) ? 50 : 0;

        // Sleep for 10 ms
        gpioDelay(INTERVAL_US);
    }

    // Stop PWM and terminate pigpio library
    gpioPWM(GPIO_PIN_1, 0);
    gpioPWM(GPIO_PIN_2, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

