#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define ECHO_PIN 17
#define TRIG_PIN 18
#define LED_PIN 27

static struct gpiod_chip *chip;
static struct gpiod_line *echo_line;
static struct gpiod_line *trig_line;
static struct gpiod_line *led_line;

void cleanup() {
    if (led_line)
        gpiod_line_release(led_line);
    if (trig_line)
        gpiod_line_release(trig_line);
    if (echo_line)
        gpiod_line_release(echo_line);
    if (chip)
        gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(echo_line, "hc-sr04_echo");
    if (ret < 0) {
        perror("Failed to request echo line as input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the trig line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        perror("Failed to get trig line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(trig_line, "hc-sr04_trig", 0);
    if (ret < 0) {
        perror("Failed to request trig line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request the LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Trigger the sensor
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    // Wait for the echo pulse
    struct timespec ts_start, ts_end;
    while (gpiod_line_get_value(echo_line) == 0) {
        nanosleep((const struct timespec[]){{0, 1000000}}, NULL); // Sleep for 1ms
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (gpiod_line_get_value(echo_line) == 1) {
        nanosleep((const struct timespec[]){{0, 1000000}}, NULL); // Sleep for 1ms
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    // Calculate the duration
    long duration = (ts_end.tv_sec - ts_start.tv_sec) * 1000000 + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000;

    // Calculate distance in cm
    double distance = duration * 0.034 / 2;

    // Print the distance
    printf("Distance: %.2f cm\n", distance);

    // Toggle the LED based on the distance
    if (distance < 30) {
        gpiod_line_set_value(led_line, 1);
    } else {
