        struct timespec start = event.ts;
        while (gpiod_line_get_value(echo_line) == 1 && running) {
            // Busy wait for the echo pin to go low
        }

        struct timespec end;
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the duration in microseconds
        long duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Calculate distance in centimeters
        double distance_cm = duration_us * 0.034 / 2.0;

        printf("Distance: %.2f cm\n", distance_cm);

