#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_2  2
#define GPIO_3  3
#define GPIO_18 18

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIOs as PWM outputs
    if (gpioSetMode(GPIO_2, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_3, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set PWM frequency to 1 kHz
    if (gpioSetPWMfrequency(GPIO_2, 1000) < 0 ||
        gpioSetPWMfrequency(GPIO_3, 1000) < 0 ||
        gpioSetPWMfrequency(GPIO_18, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        // Set different duty cycles
        gpioPWM(GPIO_2, 128);  // 50% duty cycle
        gpioPWM(GPIO_3, 64);   // 25% duty cycle
        gpioPWM(GPIO_18, 192); // 75% duty cycle

        printf("GPIO 2: 50%%, GPIO 3: 25%%, GPIO 18: 75%%\n");

        sleep(5);

        gpioPWM(GPIO_2, 0);  // 0% duty cycle
        gpioPWM(GPIO_3, 0);  // 0% duty cycle
        gpioPWM(GPIO_18, 0); // 0% duty cycle

        printf("GPIO 2: 0%%, GPIO 3: 0%%, GPIO 18: 0%%\n");

        sleep(5);
    }

    // Clean up
    gpioPWM(GPIO_2, 0);
    gpioPWM(GPIO_3, 0);
    gpioPWM(GPIO_18, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

