#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 18
#define ECHO_PIN 23
#define MAX_DISTANCE 400 // in cm

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines
    ret = gpiod_line_request_output(trig_line, "hc-sr04-trig", 0);
    if (ret < 0) {
        perror("Failed to request trig line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "hc-sr04-echo");
    if (ret < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Send trigger pulse
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    // Wait for echo start
    struct timespec timeout = { .tv_sec = 1, .tv_nsec = 0 };
    ret = gpiod_line_event_wait(echo_line, &timeout);
    if (ret < 0) {
        perror("Failed to wait for echo start");
        goto cleanup;
    } else if (ret == 0) {
        fprintf(stderr, "Echo start timeout\n");
        goto cleanup;
    }

    // Measure echo duration
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            perror("Failed to read echo line");
            goto cleanup;
        }
        if (ret == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            break;
        }
        usleep(10);
    }

    if (!running) {
        fprintf(stderr, "Interrupted\n");
        goto cleanup;
    }

    // Calculate distance
    long diff = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
    double distance = (diff / 2.0) * 0.0343; // Speed of sound in air is approximately 343 m/s

    if (distance > MAX_DISTANCE) {
        printf("Distance out of range\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }

cleanup:
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

