#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup;
    }

    // Request the line as an output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        goto cleanup;
    }

    // Set the GPIO line to high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        goto cleanup;
    }

    printf("GPIO %d set to high\n", GPIO_LINE);

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000    // 0-1000 range

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    atexit(gpioTerminate);

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PIN);
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", GPIO_PIN);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    while (running) {
        gpioPWM(GPIO_PIN, duty_cycle);
        printf("Applied duty cycle: %d\n", duty_cycle);
        duty_cycle = (duty_cycle + 100) % PWM_RANGE; // Cycle through 0 to 900
        gpioDelay(200000); // 0.2 seconds
    }

    gpioPWM(GPIO_PIN, 0); // Turn off PWM before exiting
    printf("PWM turned off\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "gpio_control"
#define GPIO_17 17
#define GPIO_18 18

static struct gpiod_chip *chip;
static struct gpiod_line *line17;
static struct gpiod_line *line18;

void cleanup() {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line17 || !line18) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as outputs
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO 17 as output");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line18, CONSUMER, 0);
    if (ret < 0) {
        perror("Failed to request GPIO 18 as output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set GPIO 17 high and GPIO 18 low
    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) {
        perror("Failed to set GPIO 17 value");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line18, 0);
    if (ret < 0) {
        perror("Failed to set GPIO 18 value");
        cleanup();
        return EXIT_FAILURE;
    }

    // Report the state
    printf("GPIO 17 is set to: %d\n", gpiod_line_get_value(line17));
    printf("GPIO 18 is set to: %d\n", gpiod_line_get_value(line18));

    // Clean up and exit
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES 3
#define GPIO_OFFSETS {18, 23, 24}

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the GPIO lines
    ret = gpiod_chip_get_lines(chip, GPIO_OFFSETS, GPIO_LINES, &lines);
    if (ret < 0) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the lines as outputs
    ret = gpiod_line_request_bulk_output(&lines, "gpio_control");
    if (ret < 0) {
        perror("Failed to request GPIO lines as outputs");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Toggle the state of each line
        for (unsigned int i = 0; i < GPIO_LINES; i++) {
            int value = gpiod_line_get_value(gpiod_line_bulk_get_line(&lines, i));
            gpiod_line_set_value(gpiod_line_bulk_get_line(&lines, i), !value);
            printf("GPIO %d set to %d\n", GPIO_OFFSETS[i], !value);
        }

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Release the lines
    gpiod_line_release_bulk(&lines);

    // Close the chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

