    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        ret = EXIT_FAILURE;
        goto exit_chip;
    }

    // Request the line as an output
    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        ret = EXIT_FAILURE;
        goto exit_line;
    }

    // Toggle the GPIO line state every 0.6 seconds
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO line value to high");
            break;
        }
        printf("GPIO 17 set to HIGH\n");
        sleep(0.6);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO line value to low");
            break;
        }
        printf("GPIO 17 set to LOW\n");
        sleep(0.6);
    }

    ret = EXIT_SUCCESS;

exit_line:
    gpiod_line_release(line);
